package com.pridesys.ticketing.module.service.impl;import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.*;import com.pridesys.ticketing.repository.*;import com.pridesys.ticketing.project.service.IProjectService;import com.pridesys.ticketing.module.service.IModuleService;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ModuleServiceImpl implements IModuleService{private final ModuleRepository modules;private final IProjectService projects;public ModuleServiceImpl(ModuleRepository m,IProjectService p){modules=m;projects=p;}public List<ModuleResponseDto> list(UserEntity a,long p){scope(a,p);return modules.findByProjectIdOrderByName(p).stream().map(this::map).toList();}public ModuleResponseDto create(UserEntity a,long p,UsersProjectsDtos.CreateModuleRequest r){scope(a,p);return map(modules.save(new ModuleEntity(p,r.name().trim(),r.description())));}public void update(UserEntity a,long p,long id,UsersProjectsDtos.UpdateModuleRequest r){scope(a,p);var m=modules.findById(id).orElseThrow();m.setName(r.name().trim());m.setDescription(r.description());if(r.active()!=null)m.setActive(r.active());modules.save(m);}public void delete(UserEntity a,long p,long id){scope(a,p);modules.deleteById(id);}private void scope(UserEntity a,long p){if(!projects.hasAccess(a,p))throw new AccessDeniedException("Project access denied");}private ModuleResponseDto map(ModuleEntity m){return new ModuleResponseDto(m.getId(),m.getProjectId(),m.getName(),m.getDescription(),m.isActive());}}
